import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import Header from "../components/header";
import Footer from "../components/footer";
import "./Results.css";

const Results = () => {
  const location = useLocation();
  const query = location.state?.query || "";

  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [favorites, setFavorites] = useState([]);
  const [user, setUser] = useState(null);

  // ✅ Load user
  useEffect(() => {
    const storedUser = JSON.parse(
      localStorage.getItem("user")
    );

    setUser(storedUser);
  }, []);

  // ✅ Load favorites from MongoDB
  useEffect(() => {
    if (!user) return;

    fetch(`http://localhost:5000/favorites/${user.email}`)
      .then((res) => res.json())
      .then((data) => {
        setFavorites(data);

        // ✅ Save also in localStorage
        localStorage.setItem(
          `favorites_${user.email}`,
          JSON.stringify(data)
        );
      })
      .catch((err) => console.log(err));

  }, [user]);

  // ✅ Fetch products
  useEffect(() => {
    const fetchData = async () => {
      if (!query) {
        setLoading(false);
        return;
      }

      try {
        const response = await fetch(
          `http://localhost:5000/api/search?q=${query}`
        );

        const data = await response.json();

        const results =
          data?.shopping_results ||
          data?.organic_results ||
          data?.inline_shopping_results ||
          [];

        const formatted = results
          .slice(0, 40)
          .map((item) => ({
            title: item.title || "No Title",
            price: item.price || "N/A",
            rating: item.rating || "3.5",

            image:
              item.thumbnail ||
              item.image ||
              "",

            link:
              item.link ||
              item.product_link ||
              item.offer_link ||
              item.source_link ||
              "#",

            source:
              item.source || "Unknown",
          }));

        setProducts(formatted);

      } catch (error) {
        console.log("ERROR:", error);

      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [query]);

  // ✅ Check favorite
  const isFavorite = (product) => {
    return favorites.some(
      (item) => item.link === product.link
    );
  };

  // ✅ Toggle favorite
  const toggleFavorite = async (product) => {

    // ❌ Not logged in
    if (!user) {
      showToast(
        "⚠️ Please Sign In / Sign Up first!"
      );
      return;
    }

    try {

      // ✅ If already exists → REMOVE
      const existing = favorites.find(
        (item) => item.link === product.link
      );

      if (existing) {

        // DELETE FROM DATABASE
        await fetch(
          `http://localhost:5000/favorites/${existing._id}`,
          {
            method: "DELETE",
          }
        );

        const updated = favorites.filter(
          (item) => item.link !== product.link
        );

        setFavorites(updated);

        // UPDATE LOCALSTORAGE
        localStorage.setItem(
          `favorites_${user.email}`,
          JSON.stringify(updated)
        );

        showToast(
          "Removed from favorites ❌"
        );

      } else {

        // ADD TO DATABASE
        await fetch(
          "http://localhost:5000/favorites",
          {
            method: "POST",

            headers: {
              "Content-Type":
                "application/json",
            },

            body: JSON.stringify({
              userEmail: user.email,

              title: product.title,
              price: product.price,
              rating: product.rating,
              image: product.image,
              link: product.link,
              source: product.source,
            }),
          }
        );

        const newFav = {
          ...product,
        };

        const updated = [
          ...favorites,
          newFav,
        ];

        setFavorites(updated);

        // UPDATE LOCALSTORAGE
        localStorage.setItem(
          `favorites_${user.email}`,
          JSON.stringify(updated)
        );

        showToast(
          "Added to favorites ⭐"
        );
      }

    } catch (error) {
      console.log(error);
    }
  };

  // ✅ Toast
  const showToast = (message) => {

    const toast = document.createElement(
      "div"
    );

    toast.innerText = message;
    toast.className = "toast";

    document.body.appendChild(toast);

    setTimeout(() => {
      toast.remove();
    }, 2000);
  };

  return (
    <>
      <Header />

      <div style={{ padding: "20px" }}>
        <h2>Results</h2>

        <p>
          Search: {query}
        </p>

        {loading ? (
          <p>Loading...</p>

        ) : products.length === 0 ? (

          <p>No products found</p>

        ) : (

          <div className="products-grid">

            {products.map((item, index) => (

              <div
                className="product-card"
                key={index}
              >

                {item.image && (
                  <img
                    src={item.image}
                    alt={item.title}
                    className="product-img"
                  />
                )}

                <h3 className="product-title">
                  {item.title}
                </h3>

                <p>
                  <b>Price:</b> {item.price}
                </p>

                <p>
                  <b>Rating:</b> {item.rating}
                </p>

                <p>
                  <b>Source:</b> {item.source}
                </p>

                <div className="btn-group">

                  {/* ⭐ FAVORITE */}
                  <button
                    className="star-btn"
                    onClick={() =>
                      toggleFavorite(item)
                    }
                  >
                    {isFavorite(item)
                      ? "★"
                      : "☆"}
                  </button>

                  {/* 🌐 WEBSITE */}
                  <button
                    onClick={() => {
                      if (
                        item.link &&
                        item.link !== "#"
                      ) {
                        window.open(
                          item.link,
                          "_blank"
                        );
                      } else {
                        alert(
                          "Link not available"
                        );
                      }
                    }}
                  >
                    Go to Website
                  </button>

                </div>

              </div>
            ))}

          </div>
        )}
      </div>

      <Footer />
    </>
  );
};

export default Results;
